begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('f1000000-0000-4000-8000-000000000001','checkout-owner@qa.invalid'),('f1000000-0000-4000-8000-000000000002','checkout-other@qa.invalid');
insert into public.tenants(id,name,slug)values('f2000000-0000-4000-8000-000000000001','Checkout QA','checkout-qa');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','owner');
insert into public.properties(id,tenant_id,name,property_type,timezone)values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Checkout QA','hotel','Pacific/Auckland');
select set_config('qa.day',(now()at time zone'Pacific/Auckland')::date::text,true);
insert into public.accommodation_types(id,tenant_id,property_id,name,kind,max_occupancy,base_rate)values('f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Checkout room','room',2,0);
insert into public.accommodation_units(id,tenant_id,property_id,type_id,name,housekeeping_status)select ('f5000000-0000-4000-8000-00000000000'||n)::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','QA'||n,'clean'from generate_series(1,2)n;
insert into public.guests(id,tenant_id,full_name)values('f6000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Checkout guest');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)select ('f7000000-0000-4000-8000-00000000000'||n)::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f6000000-0000-4000-8000-000000000001','checked_in',current_setting('qa.day')::date-case when n=1 then 1 else 0 end,current_setting('qa.day')::date+2,0,'NZD'from generate_series(1,2)n;
insert into public.unit_holds(tenant_id,property_id,unit_id,kind,reservation_id,during)select r.tenant_id,r.property_id,('f5000000-0000-4000-8000-00000000000'||n)::uuid,'reservation',r.id,daterange(r.check_in,r.check_out,'[)')from generate_series(1,2)n join public.reservations r on r.id=('f7000000-0000-4000-8000-00000000000'||n)::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.check_out_reservation('f7000000-0000-4000-8000-000000000001')$$,'42501',null,'unrelated user cannot release inventory');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.check_out_reservation('f7000000-0000-4000-8000-000000000001')$$,'settled early departure succeeds');
select is((select upper(during)from public.unit_holds where reservation_id='f7000000-0000-4000-8000-000000000001'and active),current_setting('qa.day')::date,'hold ends on hotel-local departure day');
select ok((select during@>(current_setting('qa.day')::date-1)from public.unit_holds where reservation_id='f7000000-0000-4000-8000-000000000001'and active),'past occupied night retained');
select is((select count(*)::int from public.unit_holds where reservation_id='f7000000-0000-4000-8000-000000000001'and active and during@>current_setting('qa.day')::date),0,'departure night released');
select is((select housekeeping_status from public.accommodation_units where id='f5000000-0000-4000-8000-000000000001'),'dirty','released room still requires cleaning');
select is((select count(*)::int from public.tasks where reservation_id='f7000000-0000-4000-8000-000000000001'and kind='housekeeping'and status='open'),1,'one turnaround task created before hold changes');
select is((select check_out from public.reservations where id='f7000000-0000-4000-8000-000000000001'),current_setting('qa.day')::date+2,'booked departure retained for financial history');
select lives_ok($$select public.check_out_reservation('f7000000-0000-4000-8000-000000000002')$$,'same-day departure succeeds');
select is((select count(*)::int from public.unit_holds where reservation_id='f7000000-0000-4000-8000-000000000002'and active),0,'same-day departure releases hold without invalid empty range');
select throws_ok($$select public.check_out_reservation('f7000000-0000-4000-8000-000000000002')$$,'22023',null,'repeated checkout cannot create another cleaning task');
select *from finish();rollback;
